package integration

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"
)

func TestInteractivePresentation(t *testing.T) {
	if runtime.GOOS != "linux" {
		t.Skip("uses Linux script for a pseudo-terminal")
	}
	script, err := exec.LookPath("script")
	if err != nil {
		t.Skip("script is not installed")
	}
	requireGit(t)
	bin := requireSemrelBinary(t)
	dir, cleanup := initRepo(t)
	defer cleanup()
	addTag(t, dir, "v1.0.0")
	addCommit(t, dir, "feature.txt", "feat: add feature")
	if err := os.WriteFile(filepath.Join(dir, ".semrel.yaml"), []byte("{}\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	env := append(gitEnv(dir), "CI=", "TERM=xterm", "NO_COLOR=")
	run := func(args string, extra ...string) string {
		t.Helper()
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		quoted := "'" + strings.ReplaceAll(bin, "'", "'\\''") + "'"
		cmd := exec.CommandContext(ctx, script, "-q", "-e", "-c", quoted+" "+args, "/dev/null")
		cmd.Dir, cmd.Env = dir, append(env, extra...)
		reader, writer, err := os.Pipe()
		if err != nil {
			t.Fatal(err)
		}
		defer reader.Close()
		defer writer.Close()
		cmd.Stdin = reader
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("command %s: %v\n%s", args, err, out)
		}
		return string(out)
	}
	plain := run("release --dry-run --no-color --env-file=")
	for _, want := range []string{"✓ analyzer", "→ version", "v1.0.0 → v1.1.0", "[dry-run] No changes made."} {
		if !strings.Contains(plain, want) {
			t.Fatalf("missing %q in %s", want, plain)
		}
	}
	if strings.Contains(plain, "\x1b[") || strings.Contains(plain, "release    v1.1.0 completed") {
		t.Fatalf("unexpected color or real release success in dry run: %s", plain)
	}
	colored := run("config validate --env-file=")
	if !strings.Contains(colored, "\x1b[32m✓\x1b[0m config") {
		t.Fatalf("expected styled config status: %q", colored)
	}
	noColor := run("config validate --env-file=", "NO_COLOR=1")
	if strings.Contains(noColor, "\x1b[") || !strings.Contains(noColor, "✓ config") {
		t.Fatalf("NO_COLOR should retain plain status layout: %q", noColor)
	}
	ci := run("config validate --env-file=", "CI=true")
	if strings.Contains(ci, "\x1b[") || !strings.Contains(ci, "✔  .semrel.yaml is valid") {
		t.Fatalf("CI output changed: %q", ci)
	}
	piped := exec.Command(bin, "config", "validate", "--env-file=")
	piped.Dir, piped.Env = dir, env
	pipedOutput, err := piped.CombinedOutput()
	if err != nil || string(pipedOutput) != "✔  .semrel.yaml is valid\n" {
		t.Fatalf("redirected output changed: %q, error: %v", pipedOutput, err)
	}
	output := run("config show --output json --env-file=")
	var parsed map[string]any
	if err := json.Unmarshal([]byte(output), &parsed); err != nil {
		t.Fatalf("JSON output contains presentation data: %v\n%s", err, output)
	}
	help := run("config --help")
	if !strings.Contains(help, "\x1b[36mUsage:\x1b[0m") {
		t.Fatalf("help heading is not styled: %q", help)
	}
	commitlint := run("commitlint 'feat: add feature' --no-color --env-file=")
	if !strings.Contains(commitlint, "✓ commitlint feat: add feature") {
		t.Fatalf("commitlint status is not styled: %q", commitlint)
	}
	failed := run("config validate --config missing.yaml --env-file= || true")
	if !strings.Contains(failed, "\x1b[31m✗\x1b[0m validate") || strings.Contains(failed, "Error:") {
		t.Fatalf("expected one styled command error: %q", failed)
	}

	stubs := t.TempDir()
	condition := writeScript(t, stubs, "condition", "exit 0")
	pretag := writeScript(t, stubs, "pretag", "exit 0")
	provider := writeScript(t, stubs, "provider", "exit 0")
	config := fmt.Sprintf("branches:\n  - name: main\nplugins:\n  - path: %s\n    phase: condition\n  - path: %s\n    phase: pre-tag\n  - path: %s\n    phase: release\n", condition, pretag, provider)
	if err := os.WriteFile(filepath.Join(dir, ".semrel.yaml"), []byte(config), 0o600); err != nil {
		t.Fatal(err)
	}
	release := run("release --no-color --env-file=")
	for _, want := range []string{
		"✓ condition  " + condition + " completed",
		"✓ pre-tag    " + pretag + " completed",
		"✓ git        created tag v1.1.0",
		"✓ release    " + provider + " completed",
		"✓ release    v1.1.0 completed",
	} {
		if !strings.Contains(release, want) {
			t.Fatalf("missing %q in %s", want, release)
		}
	}
}
